def merge_intervals(intervals: list) -> list[tuple[int, int]]:
    # Normalize to tuples and drop empty intervals (end <= start).
    cleaned = [(int(iv[0]), int(iv[1])) for iv in intervals if iv[1] > iv[0]]
    # Sorting creates a new list, so the input is not modified.
    cleaned.sort()

    merged: list[tuple[int, int]] = []
    for start, end in cleaned:
        if merged and start <= merged[-1][1]:
            # Overlapping or touching: extend the last interval.
            last_start, last_end = merged[-1]
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged
